import { create } from 'zustand';
import { useNavigate } from 'react-router-dom';
import { PredefinedPrompt, athenaDb } from '../database/AthenaDb';
import { DEFAULT_SCRATCHPAD_RULES } from '../constants';
import { DEFAULT_VOICE_ID } from '../constants/voices';
import { CurrencyCode } from '../utils/currency';

function getDeviceId(): string {
  let deviceId = localStorage.getItem('analyticsDeviceId');
  if (!deviceId) {
    deviceId = crypto.randomUUID();
    localStorage.setItem('analyticsDeviceId', deviceId);
  }
  return deviceId;
}

interface AuthState {
  userName: string;
  deviceId: string;
  backupInterval: number;
  customInstructions: string;
  scratchpadRules: string;
  chatWidth: 'sm' | 'md' | 'lg' | 'xl' | 'full';
  chatFontSize: number;
  themeMode: 'light' | 'dark';
  colorTheme: string;
  dateFormat: 'sv-SE' | 'en-GB' | 'en-US';
  currency: CurrencyCode;
  predefinedPrompts: PredefinedPrompt[];
  replyPredictionEnabled: boolean;
  replyPredictionModel: string;
  topicPreloadCount: number;
  messageTruncateChars: number;
  ragEnabled: boolean;
  maxContextTokens: number;
  contextWindowRatio: number;
  messageRetrievalEnabled: boolean;
  aiSummaryEnabled: boolean;
  summaryModel: string;
  defaultMaxContextMessages: number;
  showCameraButton: 'auto' | 'always' | 'never';
  ttsEnabled: boolean;
  ttsVoiceId: string;
  svgGenerationEnabled: boolean;
  setDefaultMaxContextMessages: (count: number) => void;
  setShowCameraButton: (value: 'auto' | 'always' | 'never') => void;
  setTtsEnabled: (enabled: boolean) => void;
  setTtsVoiceId: (voiceId: string) => void;
  setSvgGenerationEnabled: (enabled: boolean) => void;
  setAiSummaryEnabled: (enabled: boolean) => void;
  setSummaryModel: (model: string) => void;
  setRagEnabled: (enabled: boolean) => void;
  setMaxContextTokens: (tokens: number) => void;
  setContextWindowRatio: (ratio: number) => void;
  setMessageRetrievalEnabled: (enabled: boolean) => void;
  setReplyPredictionEnabled: (enabled: boolean) => void;
  setReplyPredictionModel: (model: string) => void;
  setTopicPreloadCount: (count: number) => void;
  setMessageTruncateChars: (chars: number) => void;
  clearAuth: () => void;
  setUserName: (name: string) => void;
  setBackupInterval: (minutes: number) => void;
  setCustomInstructions: (instructions: string) => void;
  setScratchpadRules: (rules: string) => void;
  setChatWidth: (width: 'sm' | 'md' | 'lg' | 'xl' | 'full') => void;
  setChatFontSize: (size: number) => void;
  setThemeMode: (mode: 'light' | 'dark') => void;
  setColorTheme: (theme: string) => void;
  setDateFormat: (format: 'sv-SE' | 'en-GB' | 'en-US') => void;
  setCurrency: (currency: CurrencyCode) => void;
  setPredefinedPrompts: (prompts: PredefinedPrompt[]) => void;
  addPredefinedPrompt: (prompt: PredefinedPrompt) => void;
  updatePredefinedPrompt: (prompt: PredefinedPrompt) => void;
  deletePredefinedPrompt: (id: string) => void;
}

export const useAuthStore = create<AuthState>((set) => {
  for (const key of ['llmSuggestionEnabled', 'llmModelSelected', 'llmModelDownloadStatus', 'askUserEnabled']) {
    localStorage.removeItem(key);
  }
  for (const key of ['summaryModel', 'replyPredictionModel']) {
    if (localStorage.getItem(key) === 'local') localStorage.setItem(key, 'same');
  }
  const userName = localStorage.getItem('userName') ?? '';
  const storedBackupInterval = Number(localStorage.getItem('backupInterval') ?? '30');
  const storedCustomInstructions = localStorage.getItem('customInstructions') ?? '';
  // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
  const storedScratchpadRules = localStorage.getItem('scratchpadRules') ?? DEFAULT_SCRATCHPAD_RULES;
  const storedChatWidth = (localStorage.getItem('chatWidth') as 'sm' | 'md' | 'lg' | 'full' | null) ?? 'lg';
  const storedChatFontSize = Number(localStorage.getItem('chatFontSize') ?? '16');
  const storedThemeMode = (localStorage.getItem('themeMode') as 'light' | 'dark' | null) ?? 'dark';
  const storedColorTheme = localStorage.getItem('colorTheme') ?? 'default';
  const storedDateFormat = (localStorage.getItem('dateFormat') as 'sv-SE' | 'en-GB' | 'en-US' | null) ?? 'sv-SE';
  const storedCurrency = (localStorage.getItem('currency') as CurrencyCode | null) ?? 'SEK';
  const storedReplyPredictionEnabled = localStorage.getItem('replyPredictionEnabled') === 'true';
  const storedReplyPredictionModel = localStorage.getItem('replyPredictionModel') ?? 'same';
  const storedTopicPreloadCount = Number(localStorage.getItem('topicPreloadCount') ?? '5');
  const storedMessageTruncateChars = Number(localStorage.getItem('messageTruncateChars') ?? '500');
  const storedRagEnabled = localStorage.getItem('ragEnabled') === 'true'; // default false
  const storedMaxContextTokens = Number(localStorage.getItem('maxContextTokens') ?? '16000');
  const storedContextWindowRatio = Number(localStorage.getItem('contextWindowRatio') ?? '0.75');
  const storedMessageRetrievalEnabled = localStorage.getItem('messageRetrievalEnabled') !== 'false'; // default true
  const storedAiSummaryEnabled = localStorage.getItem('aiSummaryEnabled') === 'true';
  const storedSummaryModel = localStorage.getItem('summaryModel') ?? 'same';
  const storedDefaultMaxContextMessages = Number(localStorage.getItem('defaultMaxContextMessages') ?? '10');
  const storedShowCameraButton = (localStorage.getItem('showCameraButton') as 'auto' | 'always' | 'never' | null) ?? 'auto';
  const storedTtsEnabled = localStorage.getItem('ttsEnabled') === 'true';
  const storedTtsVoiceId = localStorage.getItem('ttsVoiceId') ?? DEFAULT_VOICE_ID;
  const storedSvgGenerationEnabled = localStorage.getItem('svgGenerationEnabled') !== 'false'; // default true
  return {
    userName: userName,
    deviceId: getDeviceId(),
    backupInterval: storedBackupInterval,
    customInstructions: storedCustomInstructions,
    // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
    scratchpadRules: storedScratchpadRules,
    chatWidth: storedChatWidth,
    chatFontSize: storedChatFontSize,
    themeMode: storedThemeMode,
    colorTheme: storedColorTheme,
    dateFormat: storedDateFormat,
    currency: storedCurrency,
    predefinedPrompts: [],
    replyPredictionEnabled: storedReplyPredictionEnabled,
    replyPredictionModel: storedReplyPredictionModel,
    topicPreloadCount: storedTopicPreloadCount,
    messageTruncateChars: storedMessageTruncateChars,
    ragEnabled: storedRagEnabled,
    maxContextTokens: storedMaxContextTokens,
    contextWindowRatio: storedContextWindowRatio,
    messageRetrievalEnabled: storedMessageRetrievalEnabled,
    aiSummaryEnabled: storedAiSummaryEnabled,
    summaryModel: storedSummaryModel,
    defaultMaxContextMessages: storedDefaultMaxContextMessages,
    showCameraButton: storedShowCameraButton,
    ttsEnabled: storedTtsEnabled,
    ttsVoiceId: storedTtsVoiceId,
    svgGenerationEnabled: storedSvgGenerationEnabled,
    clearAuth: (): void => {
      localStorage.removeItem('userName');
      localStorage.removeItem('customInstructions');
      localStorage.removeItem('chatWidth');
      localStorage.removeItem('chatFontSize');
      localStorage.removeItem('messageRetrievalEnabled');
      localStorage.removeItem('backupInterval');
      localStorage.removeItem('scratchpadRules');
      localStorage.removeItem('llmSuggestionEnabled');
      localStorage.removeItem('replyPredictionEnabled');
      localStorage.removeItem('replyPredictionModel');
      localStorage.removeItem('llmModelSelected');
      localStorage.removeItem('llmModelDownloadStatus');
      localStorage.removeItem('topicPreloadCount');
      localStorage.removeItem('messageTruncateChars');
      localStorage.removeItem('ragEnabled');
      localStorage.removeItem('maxContextTokens');
      localStorage.removeItem('contextWindowRatio');
      localStorage.removeItem('aiSummaryEnabled');
      localStorage.removeItem('summaryModel');
      localStorage.removeItem('defaultMaxContextMessages');
      localStorage.removeItem('showCameraButton');
      localStorage.removeItem('ttsEnabled');
      localStorage.removeItem('ttsVoiceId');
      localStorage.removeItem('svgGenerationEnabled');
      localStorage.removeItem('currency');
      void athenaDb.predefinedPrompts.clear().catch((err: unknown) => {
        console.error('Failed to clear predefined prompts:', err);
      });
      set({
        userName: '',
        customInstructions: '',
        chatWidth: 'lg',
        chatFontSize: 16,
        themeMode: 'dark',
        colorTheme: 'default',
        dateFormat: 'sv-SE',
        currency: 'SEK',
        predefinedPrompts: [],
        replyPredictionEnabled: false,
        replyPredictionModel: 'same',
        ragEnabled: false,
        maxContextTokens: 16000,
        contextWindowRatio: 0.75,
        messageRetrievalEnabled: true,
        aiSummaryEnabled: false,
        defaultMaxContextMessages: 10,
        showCameraButton: 'auto',
        ttsEnabled: false,
        ttsVoiceId: DEFAULT_VOICE_ID,
        svgGenerationEnabled: true,
      });
    },
    setShowCameraButton: (value: 'auto' | 'always' | 'never'): void => {
      localStorage.setItem('showCameraButton', value);
      set({ showCameraButton: value });
    },
    setTtsEnabled: (enabled: boolean): void => {
      localStorage.setItem('ttsEnabled', String(enabled));
      set({ ttsEnabled: enabled });
    },
    setTtsVoiceId: (voiceId: string): void => {
      localStorage.setItem('ttsVoiceId', voiceId);
      set({ ttsVoiceId: voiceId });
    },
    setSvgGenerationEnabled: (enabled: boolean): void => {
      localStorage.setItem('svgGenerationEnabled', String(enabled));
      set({ svgGenerationEnabled: enabled });
    },
    setDefaultMaxContextMessages: (count: number): void => {
      localStorage.setItem('defaultMaxContextMessages', String(count));
      set({ defaultMaxContextMessages: count });
    },
    setReplyPredictionEnabled: (enabled: boolean): void => {
      localStorage.setItem('replyPredictionEnabled', String(enabled));
      set({ replyPredictionEnabled: enabled });
    },
    setReplyPredictionModel: (model: string): void => {
      localStorage.setItem('replyPredictionModel', model);
      set({ replyPredictionModel: model });
    },
    setTopicPreloadCount: (count: number): void => {
      localStorage.setItem('topicPreloadCount', String(count));
      set({ topicPreloadCount: count });
    },
    setMessageTruncateChars: (chars: number): void => {
      localStorage.setItem('messageTruncateChars', String(chars));
      set({ messageTruncateChars: chars });
    },
    setRagEnabled: (enabled: boolean): void => {
      localStorage.setItem('ragEnabled', String(enabled));
      set({ ragEnabled: enabled });
    },
    setMaxContextTokens: (tokens: number): void => {
      localStorage.setItem('maxContextTokens', String(tokens));
      set({ maxContextTokens: tokens });
    },
    setContextWindowRatio: (ratio: number): void => {
      const clamped = Math.max(0.1, Math.min(0.95, ratio));
      localStorage.setItem('contextWindowRatio', String(clamped));
      set({ contextWindowRatio: clamped });
    },
    setMessageRetrievalEnabled: (enabled: boolean): void => {
      localStorage.setItem('messageRetrievalEnabled', String(enabled));
      set({ messageRetrievalEnabled: enabled });
    },
    setAiSummaryEnabled: (enabled: boolean): void => {
      localStorage.setItem('aiSummaryEnabled', String(enabled));
      set({ aiSummaryEnabled: enabled });
    },
    setSummaryModel: (model: string): void => {
      localStorage.setItem('summaryModel', model);
      set({ summaryModel: model });
    },
    setUserName: (userName: string): void => {
      localStorage.setItem('userName', userName);
      set({ userName });
    },
    setBackupInterval: (minutes: number): void => {
      localStorage.setItem('backupInterval', String(minutes));
      set({ backupInterval: minutes });
    },
    setCustomInstructions: (instructions: string): void => {
      localStorage.setItem('customInstructions', instructions);
      set({ customInstructions: instructions });
    },
    setScratchpadRules: (rules: string): void => {
      localStorage.setItem('scratchpadRules', rules);
      set({ scratchpadRules: rules });
    },
    setChatWidth: (width: 'sm' | 'md' | 'lg' | 'xl' | 'full'): void => {
      localStorage.setItem('chatWidth', width);
      set({ chatWidth: width });
    },
    setChatFontSize: (size: number): void => {
      localStorage.setItem('chatFontSize', String(size));
      set({ chatFontSize: size });
    },
    setThemeMode: (mode: 'light' | 'dark'): void => {
      localStorage.setItem('themeMode', mode);
      set({ themeMode: mode });
    },
    setColorTheme: (theme: string): void => {
      localStorage.setItem('colorTheme', theme);
      set({ colorTheme: theme });
    },
    setDateFormat: (format: 'sv-SE' | 'en-GB' | 'en-US'): void => {
      localStorage.setItem('dateFormat', format);
      set({ dateFormat: format });
    },
    setCurrency: (currency: CurrencyCode): void => {
      localStorage.setItem('currency', currency);
      set({ currency });
    },
    setPredefinedPrompts: (predefinedPrompts: PredefinedPrompt[]): void => {
      set({ predefinedPrompts });
    },
    addPredefinedPrompt: (prompt: PredefinedPrompt): void => {
      set((state) => ({ predefinedPrompts: [...state.predefinedPrompts, prompt] }));
      void athenaDb.predefinedPrompts.add(prompt).catch((err: unknown) => {
        console.error('Failed to add predefined prompt:', err);
      });
    },
    updatePredefinedPrompt: (prompt: PredefinedPrompt): void => {
      set((state) => ({
        predefinedPrompts: state.predefinedPrompts.map((p) => (p.id === prompt.id ? prompt : p)),
      }));
      void athenaDb.predefinedPrompts.put(prompt).catch((err: unknown) => {
        console.error('Failed to update predefined prompt:', err);
      });
    },
    deletePredefinedPrompt: (id: string): void => {
      set((state) => ({
        predefinedPrompts: state.predefinedPrompts.filter((p) => p.id !== id),
      }));
      void athenaDb.predefinedPrompts.delete(id).catch((err: unknown) => {
        console.error('Failed to delete predefined prompt:', err);
      });
    },
  };
});

// Load predefined prompts from DB on init
void athenaDb.predefinedPrompts
  .toArray()
  .then((prompts) => {
    if (prompts.length === 0) {
      const seedPrompts: PredefinedPrompt[] = [
        {
          id: 'seed-mermaid-capability',
          name: 'Mermaid Diagrams',
          content:
            'You can generate mermaid diagrams when they would help visualize concepts, processes, architectures, or relationships. Use ```mermaid code blocks for diagram definitions.',
        },
      ];
      void athenaDb.predefinedPrompts.bulkAdd(seedPrompts).then(() => {
        useAuthStore.getState().setPredefinedPrompts(seedPrompts);
      });
    } else {
      useAuthStore.getState().setPredefinedPrompts(prompts);
    }
  })
  .catch((err: unknown) => {
    console.error('Failed to load predefined prompts:', err);
  });

export const useLogout = (): (() => void) => {
  const navigate = useNavigate();

  return (): void => {
    useAuthStore.getState().clearAuth();
    void navigate('/settings', { replace: true });
  };
};
